    cols.forEach(c => { const s = new Set(); E.emp.forEach(o => { if (o.v[c.name] !== '') s.add(o.v[c.name]); }); c.d = s.size; c.ok = !skipT.has(c.type) && c.name !== E.fileCol && c.name !== E.nameCol && c.name !== 'Title' && s.size >= 2 && s.size <= 150; if (/^whs.?_?link$/i.test(c.name) || /^whs.?_?link$/i.test(c.label)) c.ok = !skipT.has(c.type) && s.size >= 2; });
    E.cols = cols; let saved = null; try { saved = JSON.parse(localStorage.getItem(LSF) || 'null'); } catch (e) { }
