    E.sel = saved && saved.filter(n => okNames.includes(n)).length ? saved.filter(n => okNames.includes(n)) : cols.filter(c => c.ok && c.d <= 60).slice(0, 10).map(c => c.name);
    { const wl = cols.find(c => c.ok && (/^whs.?_?link$/i.test(c.name) || /^whs.?_?link$/i.test(c.label))); let done = ''; try { done = localStorage.getItem(LSF + '_wl') || ''; } catch (e) { } if (wl && !done && !E.sel.includes(wl.name)) { E.sel = cols.filter(c => E.sel.includes(c.name) || c.name === wl.name).map(c => c.name); try { localStorage.setItem(LSF, JSON.stringify(E.sel)); } catch (e) { } } try { localStorage.setItem(LSF + '_wl', '1'); } catch (e) { } }
    let g = ''; try { g = localStorage.getItem(LSG) || ''; } catch (e) { } E.grp = E.sel.includes(g) ? g : (E.sel.find(c => /sect/i.test(c)) || E.sel[0] || '');
