      E.loaded = true; E.grace = (typeof at !== 'undefined' && at.grace) || 15; if (!E.f.from && at.rows.length) { const ds = at.rows.map(r => r.date).sort(); E.f.from = ds[0]; E.f.to = ds[ds.length - 1]; }
